SELECT     ia.LOCATION                                     AS \"Location ID\",     ia.LOC_TYPE                                     AS \"Location Type\",     CASE ia.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                             AS \"Location Name\",     ia.ITEM                                         AS \"Item ID\",     im.ITEM_DESC                                    AS \"Item Description\",     sec.ALLOWED_USERS AS \"Dept Allowed Users\",     im.DEPT                                         AS \"Department Number\",     d.DEPT_NAME                                     AS \"Department Name\",     im.CLASS                                        AS \"Class Number\",     c.CLASS_NAME                                    AS \"Class Name\",     im.SUBCLASS                                     AS \"Subclass Number\",     sc.SUB_NAME                                     AS \"Subclass Name\",     im.STANDARD_UOM                                 AS \"Unit of Measure\",     im.STATUS                                       AS \"Item Status\",     ia.ID                                           AS \"Adjustment ID\",     ia.ADJ_DATE                                     AS \"Adjustment Date\",     TO_CHAR(ia.ADJ_DATE, 'YYYY-MM')                AS \"Adjustment Year Month\",     ia.REASON                                       AS \"Reason Code\",     rt.REASON_DESC                                  AS \"Reason Description\",     ia.CREATE_ID                                    AS \"Created By\",     ia.CREATE_DATETIME                              AS \"Created Date Time\",     ia.PREV_QTY                                     AS \"Quantity Before Adjustment\",     ia.ADJ_QTY                                      AS \"Adjusted Quantity\",     (ia.PREV_QTY + ia.ADJ_QTY)                     AS \"Quantity After Adjustment\",     CASE         WHEN ia.ADJ_QTY &gt; 0 THEN 'Positive - Stock Increase'         WHEN ia.ADJ_QTY &lt; 0 THEN 'Negative - Stock Decrease'         ELSE                     'No Change'     END                                             AS \"Adjustment Direction\",     ia.ADJ_WEIGHT                                   AS \"Adjusted Weight\",     ia.ADJ_WEIGHT_UOM                               AS \"Weight Unit of Measure\",     ia.USER_ID                                      AS \"Adjusted By User\",     ia.COMMENTS                                     AS \"Adjustment Comments\",     ils.UNIT_COST                                   AS \"Unit Cost\",     ils.AV_COST                                     AS \"Weighted Average Cost\",     il.SELLING_UNIT_RETAIL                          AS \"Unit Retail Price\",     ROUND(ia.ADJ_QTY * ils.UNIT_COST,  4)          AS \"Adjustment Cost Value\",     ROUND(ia.ADJ_QTY * il.SELLING_UNIT_RETAIL, 4)  AS \"Adjustment Retail Value\",     ils.STOCK_ON_HAND                               AS \"Current Stock on Hand\",     (ils.STOCK_ON_HAND - ia.ADJ_QTY)               AS \"Stock on Hand Before\",     ils.STOCK_ON_HAND                               AS \"Stock on Hand After\",     td.TRAN_DATE                                    AS \"Transaction Date\",     td.TRAN_CODE                                    AS \"Transaction Code\",     td.TOTAL_COST                                   AS \"Transaction Total Cost\",     td.TOTAL_RETAIL                                 AS \"Transaction Total Retail\",     td.VAT_RATE                                     AS \"VAT Rate\",     td.REF_NO_1                                     AS \"Reference Number\",     td.GL_REF_NO                                    AS \"GL Reference Number\",     td.ADJ_CODE                                     AS \"Adjustment Code\",     p.HALF_NO                                       AS \"Fiscal Half\",     p.CURR_454_MONTH                                AS \"Fiscal Month 454\",     p.CURR_454_WEEK                                 AS \"Fiscal Week 454\",     p.CURR_454_YEAR                                 AS \"Fiscal Year 454\" FROM     MFCS_RDS.RDS_WV_INV_ADJ                 ia     LEFT JOIN MFCS_RDS.RDS_WV_INV_ADJ_REASON_TL  rt                                                 ON  ia.REASON       = rt.REASON                                                 AND rt.LANG          = 1              JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        im  ON  ia.ITEM        = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS               d   ON  im.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c   ON  im.DEPT        = c.DEPT                                                  AND  im.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc  ON  im.DEPT        = sc.DEPT                                                  AND  im.CLASS       = sc.CLASS                                                  AND  im.SUBCLASS    = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_STORE          st  ON  ia.LOCATION    = st.STORE                                                  AND  ia.LOC_TYPE    = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH             wh  ON  ia.LOCATION    = wh.WH                                                  AND  ia.LOC_TYPE    = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  ils  ON  ia.ITEM        = ils.ITEM                                                   AND  ia.LOCATION   = ils.LOC                                                   AND  ia.LOC_TYPE   = ils.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC       il  ON  ia.ITEM        = il.ITEM                                                  AND  ia.LOCATION    = il.LOC                                                  AND  ia.LOC_TYPE    = il.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_TRAN_DATA      td  ON  ia.ITEM        = td.ITEM                                                  AND  ia.LOCATION    = td.LOCATION                                                  AND  TRUNC(ia.ADJ_DATE) = TRUNC(td.TRAN_DATE)                                                  AND  td.TRAN_CODE   IN (22, 23)       LEFT JOIN MFCS_RDS.RDS_WV_