D\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Department Number\"],\"expressionSourceColumns\":[\"Department Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Department Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Department Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class Number\"],\"expressionSourceColumns\":[\"Class Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass Number\"],\"expressionSourceColumns\":[\"Subclass Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Adjustment ID\"],\"expressionSourceColumns\":[\"Adjustment ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Adjustment ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Adjustment ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Reason Code\"],\"expressionSourceColumns\":[\"Reason Code\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Reason Code\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Reason Code\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"},{\"id\":\"7\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Transaction Code\"],\"expressionSourceColumns\":[\"Transaction Code\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Transaction Code\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Transaction Code\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"6\"},{\"id\":\"8\",\"type\":\"EDIT_COLUMN\",\"sourceColumns\":[],\"expressionSourceColumns\":[],\"outputColumns\":[{\"name\":\"Current Session User\",\"displayName\":\"Current Session User\",\"exclude\":false,\"datatype\":\"varchar(4000)\",\"aggrRule\":\"none\",\"uiOptions\":{\"prepColumnName\":\"Current Session User\",\"originalColumnName\":\"Current Session User\",\"isUserCalculation\":true,\"isApplied\":false,\"transformEngine\":\"bis\"},\"sourceexpr\":\"\\\"Current Session User\\\"\",\"errorStatus\":\"\"}],\"options\":{\"name\":\"Current Session User\",\"expression\":\"VALUEOF(NQ_SESSION.USER)\",\"outputColumnDisplayName\":\"Current Session User\",\"outputColumnDataType\":\"varchar(4000)\",\"outputColumnAggrRule\":\"none\",\"isEditorValid\":true,\"afterColumn\":\"Dept Allowed Users\",\"createColumn\":true},\"applied\":true,\"inplace\":false,\"ren