-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n        fgm.FILTER_MERCH_ID                                            AS DEPT,\\n        LISTAGG(su.APPLICATION_USER_ID, ',')\\n            WITHIN GROUP (ORDER BY su.APPLICATION_USER_ID)             AS ALLOWED_USERS\\n    FROM  MFCS_RDS.RDS_WV_FILTER_GROUP_MERCH fgm\\n    JOIN  MFCS_RDS.RDS_WV_SEC_USER_GROUP     sug ON fgm.SEC_GROUP_ID = sug.GROUP_ID\\n    JOIN  MFCS_RDS.RDS_WV_SEC_USER           su  ON sug.USER_SEQ    = su.USER_SEQ\\n    WHERE fgm.FILTER_MERCH_LEVEL = 'P'\\n    GROUP BY fgm.FILTER_MERCH_ID\\n) sec ON im.DEPT = sec.DEPT \\n\\nWHERE\\n    ia.ADJ_DATE &gt;= ADD_MONTHS(SYSDATE, -3)  \\nORDER BY\\n    ia.ADJ_DATE     DESC,\\n    ia.LOCATION,\\n    ia.ITEM;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"DC Adjustments","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-06-12T13:30:33.114+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'DS_RPT_001'","parent-namespace":"ReCommon","parent-name":"DS_RPT_001","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'DS_RPT_001'"}

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT     ia.LOCATION                                         AS \"Location ID\",     ia.LOC_TYPE                                         AS \"Location Type\",     CASE ia.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                 AS \"Location Name\",     ia.REASON                                           AS \"Reason Code\",     rt.REASON_DESC                                      AS \"Reason Description\",     COUNT(ia.ID)                                        AS \"Total Adjustments\",     SUM(ia.ADJ_QTY)                                     AS \"Total Adjusted Units\",     SUM(CASE WHEN ia.ADJ_QTY &gt; 0 THEN ia.ADJ_QTY ELSE 0 END) AS \"Positive Adjusted Units\",     SUM(CASE WHEN ia.ADJ_QTY &lt; 0 THEN ia.ADJ_QTY ELSE 0 END) AS \"Negative Adjusted Units\",     ROUND(SUM(ia.ADJ_QTY * ils.UNIT_COST),  2)         AS \"Total Adjustment Cost\",     ROUND(SUM(CASE WHEN ia.ADJ_QTY &gt; 0                    THEN ia.ADJ_QTY * ils.UNIT_COST                    ELSE 0 END), 2)                      AS \"Positive Adjustment Cost\",     ROUND(SUM(CASE WHEN ia.ADJ_QTY &lt; 0                    THEN ia.ADJ_QTY * ils.UNIT_COST                    ELSE 0 END), 2)                      AS \"Negative Adjustment Cost\",     ROUND(SUM(ia.ADJ_QTY * il.SELLING_UNIT_RETAIL), 2) AS \"Total Adjustment Retail\",     ROUND(SUM(CASE WHEN ia.ADJ_QTY &gt; 0                    THEN ia.ADJ_QTY * il.SELLING_UNIT_RETAIL                    ELSE 0 END), 2)                      AS \"Positive Adjustment Retail\",     ROUND(SUM(CASE WHEN ia.ADJ_QTY &lt; 0                    THEN ia.ADJ_QTY * il.SELLING_UNIT_RETAIL                    ELSE 0 END), 2)                      AS \"Negative Adjustment Retail\",     ROUND(SUM(ia.ADJ_QTY * (il.SELLING_UNIT_RETAIL - ils.UNIT_COST)), 2)                                                         AS \"Gross Profit Impact\"  FROM     MFCS_RDS.RDS_WV_INV_ADJ                    ia      LEFT JOIN MFCS_RDS.RDS_WV_INV_ADJ_REASON_TL rt                                                 ON  ia.REASON       = rt.REASON                                                 AND rt.LANG          = 1      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st  ON  ia.LOCATION = st.STORE                                                     AND  ia.LOC_TYPE = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH                wh  ON  ia.LOCATION = wh.WH                                                     AND  ia.LOC_TYPE = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils  ON  ia.ITEM     = ils.ITEM                                                     AND  ia.LOCATION = ils.LOC                                                     AND  ia.LOC_TYPE = ils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC           il  ON  ia.ITEM     = il.ITEM                                                     AND  ia.LOCATION = il.LOC                                                     AND  ia.LOC_TYPE = il.LOC_TYPE  WHERE     ia.ADJ_DATE &gt;= ADD_MONTHS(SYSDATE, -3)    GROUP BY     ia.LOCATION,     ia.LOC_TYPE,     CASE ia.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END,     ia.REASON,     rt.REASON_DESC  ORDER BY     ia.LOCATION,     ia.REASON</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Location ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Type</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Name</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column><ds:column><ds:name>Reason Code</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Reason Description</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>Total Adjustments</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Total Adjusted Units</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Positive Adjusted Units</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Negative Adjusted Units</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Total Adjustment Cost</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Positive Adjustment Cost</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Negative Adjustment Cost</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Total Adjustment Retail</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Positive Adjustment Retail</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Negative Adjustment Retail</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>Gross Profit Impact</ds:name><ds:datatype>number</ds:datatype></ds:column></ds:columns></ds:table></ds:tables><ds:prepareTables><ds:table name=\"Data\" transformed=\"true\"><ds:columns><ds:column><ds:name>Location ID</ds:name></ds:column><ds:column><ds:name>Location Type</ds:name></ds:column><ds:column><ds:name>Location Name</ds:name></ds:column><ds:column><ds:name>Reason Code</ds:name></ds:column><ds:column><ds:name>Reason Description</ds:name></ds:column><ds:column><ds:name>Total Adjustments</ds:name></ds:column><ds:column><ds:name>Total Adjusted Units</ds:name></ds:column><ds:column><ds:name>Positive Adjusted Units</ds:name></ds:column><ds:column><ds:name>Negative Adjusted Units</ds:name></ds:column><ds:column><ds:name>Total Adjustment Cost</ds:name></ds:column><ds:column><ds:name>Positive Adjustment Cost</ds:name></ds:column><ds:column><ds:name>Negative Adjustment Cost</ds:name></ds:column><ds:column><ds:name>Total Adjustment Retail</ds:name></ds:column><ds:column><ds:name>Positive Adjustment Retail</ds:name></ds:column><ds:column><ds:name>Negative Adjustment Retail</ds:name></ds:column><ds:column><ds:name>Gross Pr